SELECT CASE WHEN m.entry_quality_score<55 THEN 'a50-54' WHEN m.entry_quality_score<60 THEN 'b55-59' WHEN m.entry_quality_score<70 THEN 'c60-69' ELSE 'd70+' END AS eq_bucket, CASE WHEN s.atr_percent<0.1667 THEN 'lo<0.167' WHEN s.atr_percent<0.25 THEN 'mid' ELSE 'hi>=0.25' END AS atr_bucket, COUNT(*) AS n, SUM(p.realized_pnl>0) AS wins, ROUND(AVG((p.exit_price-p.entry_price)/p.entry_price*100),4) AS avg_gross_pct FROM paper_position p JOIN trade_signal s ON s.id=p.signal_id LEFT JOIN wallet_managed_position m ON m.entry_signal_id=p.signal_id WHERE p.opened_at>='2026-10-11 00:00:00' AND p.status IN ('CLOSED','STOPPED') GROUP BY eq_bucket, atr_bucket ORDER BY eq_bucket, atr_bucket LIMIT 40